    {
      "name": "Category Tag",
      "role": "Pill-shaped API category labels — 'Start an HTTP server', 'Use Redis', etc.",
      "description": "9999px radius, background transparent, 1px border #3b3f4b. Text: #e5e7eb, system-ui 13px weight 500. Padding 8px 16px. Arranged in a centered cloud layout. No fill — these are navigation hints, not actions."
